import java.nio.file.*;import java.awt.image.*;import javax.imageio.*;import com.google.gson.*;import net.runelite.cache.fs.*;import net.runelite.cache.definitions.*;import net.runelite.cache.definitions.loaders.*;
public class ExportSkillSprites {public static void main(String[]args)throws Exception{Path r=Path.of(args[0]).resolve("Reference/sprites");Files.createDirectories(r);try(Store s=new Store(Path.of(args[1]).toFile())){s.load();for(int id:new int[]{214,215,216,217,218,219}){Archive a=s.findIndex(8).getArchive(id);byte[] b=a.getFiles(s.getStorage().loadArchive(a)).getFiles().iterator().next().getContents();SpriteDefinition d=new SpriteLoader().load(id,b)[0];BufferedImage im=new BufferedImage(d.getWidth(),d.getHeight(),BufferedImage.TYPE_INT_ARGB);int[]px=d.getPixels().clone();for(int i=0;i<px.length;i++)if(px[i]!=0)px[i]|=0xff000000;im.setRGB(0,0,d.getWidth(),d.getHeight(),px,0,d.getWidth());ImageIO.write(im,"PNG",r.resolve(id+".png").toFile());Files.write(r.resolve(id+".dat"),b);Files.writeString(r.resolve(id+".json"),new Gson().toJson(d));System.out.println(id+": "+d.getWidth()+"x"+d.getHeight());}}}}
